import { test } from "node:test";
import assert from "node:assert/strict";
import { chargeInvoice } from "../src/billing.js";
import { Gateway } from "../src/gateway.js";
import { openInvoice } from "../src/invoices.js";
import { retryFailedInvoices, RETRY_DELAYS_MS } from "../src/retries.js";

const sub = { id: "sub_t", customer: "cus_test", priceCents: 4900, active: true };
const T0 = new Date("2026-10-01T06:00:00Z");
const after = (ms) => new Date(T0.getTime() + ms);

async function failedInvoice(script) {
  const gw = new Gateway({ script });
  const inv = await chargeInvoice(openInvoice(sub, "2026-10"), gw, { now: T0 });
  assert.equal(inv.status, "failed");
  return { gw, inv };
}

test("a due failed invoice is retried and paid", async () => {
  const { gw, inv } = await failedInvoice(["unavailable", "unavailable", "unavailable"]);
  const { retried } = await retryFailedInvoices([inv], gw, after(RETRY_DELAYS_MS[0]));
  assert.deepEqual(retried, [inv]);
  assert.equal(inv.status, "paid");
  assert.equal(inv.attempts.length, 4);
  assert.equal(gw.chargesFor("cus_test").length, 1);
});

test("a failed invoice that is not yet due is left alone", async () => {
  const { gw, inv } = await failedInvoice(["unavailable", "unavailable", "unavailable"]);
  const calls = gw.calls;
  const { retried } = await retryFailedInvoices([inv], gw, after(RETRY_DELAYS_MS[0] - 1));
  assert.equal(retried.length, 0);
  assert.equal(gw.calls, calls);
  assert.equal(inv.status, "failed");
});

test("at most one retry per invoice per run, even when the next one is also due", async () => {
  const { gw, inv } = await failedInvoice(["unavailable", "unavailable", "unavailable", "unavailable"]);
  const far = after(365 * 24 * 60 * 60 * 1000);
  const calls = gw.calls;
  await retryFailedInvoices([inv], gw, far);
  assert.equal(gw.calls, calls + 1);
  assert.equal(inv.status, "failed");
  assert.equal(inv.retries, 1);
});

test("the next retry waits for its own delay after the last attempt", async () => {
  const { gw, inv } = await failedInvoice(Array(5).fill("unavailable"));
  const t1 = after(RETRY_DELAYS_MS[0]);
  await retryFailedInvoices([inv], gw, t1);
  const calls = gw.calls;
  await retryFailedInvoices([inv], gw, new Date(t1.getTime() + RETRY_DELAYS_MS[1] - 1));
  assert.equal(gw.calls, calls);
  await retryFailedInvoices([inv], gw, new Date(t1.getTime() + RETRY_DELAYS_MS[1]));
  assert.equal(gw.calls, calls + 1);
});

test("retries stop once the schedule is used up", async () => {
  const { gw, inv } = await failedInvoice(Array(10).fill("unavailable"));
  let now = T0;
  for (const d of RETRY_DELAYS_MS) {
    now = new Date(now.getTime() + d);
    await retryFailedInvoices([inv], gw, now);
  }
  const calls = gw.calls;
  await retryFailedInvoices([inv], gw, after(365 * 24 * 60 * 60 * 1000));
  assert.equal(gw.calls, calls);
  assert.equal(inv.retries, RETRY_DELAYS_MS.length);
});

test("paid, declined and open invoices are never retried", async () => {
  const gw = new Gateway({ script: ["ok", "declined"] });
  const paid = await chargeInvoice(openInvoice({ ...sub, id: "a" }, "2026-10"), gw, { now: T0 });
  const declined = await chargeInvoice(openInvoice({ ...sub, id: "b" }, "2026-10"), gw, { now: T0 });
  const open = openInvoice({ ...sub, id: "c" }, "2026-10");
  const calls = gw.calls;
  const { retried } = await retryFailedInvoices([paid, declined, open], gw, after(365 * 24 * 60 * 60 * 1000));
  assert.equal(retried.length, 0);
  assert.equal(gw.calls, calls);
  assert.deepEqual([paid.status, declined.status, open.status], ["paid", "declined", "open"]);
});

test("a retry after a timeout does not charge the customer twice", async () => {
  // Every try times out: the provider charged on the first, and the replies were all lost.
  const { gw, inv } = await failedInvoice(["timeout", "timeout", "timeout"]);
  assert.equal(gw.chargesFor("cus_test").length, 1);
  await retryFailedInvoices([inv], gw, after(RETRY_DELAYS_MS[0]));
  assert.equal(inv.status, "paid");
  assert.equal(gw.chargesFor("cus_test").length, 1);
  assert.equal(inv.chargeId, gw.chargesFor("cus_test")[0].id);
});

test("a declined retry is final", async () => {
  const { gw, inv } = await failedInvoice(["unavailable", "unavailable", "unavailable", "declined"]);
  await retryFailedInvoices([inv], gw, after(RETRY_DELAYS_MS[0]));
  assert.equal(inv.status, "declined");
  const calls = gw.calls;
  await retryFailedInvoices([inv], gw, after(365 * 24 * 60 * 60 * 1000));
  assert.equal(gw.calls, calls);
});
